quests[89558] = { id = 89558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Darkheart Thicket, Heroic", description = "A team of timerunners, armed with potent artifacts, can overcome many threats.\n\nLet us see whether you can handle Darkheart Thicket.", progress = "Well, you aren't dead. That's a good sign.", completion = "Very good results. Exceeds expectations.", objectives = "Complete Darkheart Thicket on Heroic difficulty or higher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89559] = { id = 89559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reasonless Worship", description = "Ahead is an old shrine. Nobody knows anymore what we worshipped there or why, but it was a place my mother loved.\n\nIt would honor her if we put a stone from it on de pyre with her.", progress = "We both know dat de shrine is a place dat pleased our mother.\n\nI can't say she knew dat much about us.", completion = "The others in de tribe still revere mother and mourn her death.\n\nBut since she died, I've mostly just been missin' Iz'ken.\n\nShe drove my brother away.\n\nBut... her death has brought him back. At least for dis ritual.", objectives = "Collect a Weathered Shrine Piece.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89560] = { id = 89560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Quiet Farewell", description = "Now we set up de bonfire to burn de body. Destroying the body means it cannot be used by de Vilebranch for evil and makes sure de spirit finds rest.\n\nIt still chills me how quiet she is now.\n\nThe tribe should be gatherin' down at de Funerary Coast.", progress = "It's time. We are ready.", completion = "Thank you for helpin' us on dis journey, {name}.\n\nI didn't think Iz'ken would come, and he didn't think he'd be welcome.\n\nI think Iz'ken and I realize now... de worst trick our mother pulled was pittin' us against each other.", objectives = "Setup the bonfire for Chana and Iz'ken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89561] = { id = 89561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrapped Up", description = "Shad'anis has told me about you--a fleshling with the ability to travel to Untethered Space. How do you accomplish such a feat? Wait--let me deduce.\n \nIt must be those wraps you wear as a cloak. They have been modified by a Reshii Ribbon. I have not seen such a thing since the Devouring War. Very nice. Classic.\n \nDo you want classic? Or do you want powerful? I can enhance your Reshii Wraps with modern technomancy techniques to better face the dangers of Untethered Space.", progress = "Enhancing the Reshii Wraps is paramount to your survival.", completion = "Thank you, {name}. Your adventures in Untethered Space will help clear the way for our Phase Divers to recover the energy that would have been lost to the Void.", objectives = "Talk to Hashim about your Reshii Wraps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89565] = { id = 89565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of Mourning", description = "Hash'ura, could I ask for your aid?\n\nMy mother passed recently, and I'm de one responsible for performin' her death rituals. It's a lotta work for one person to do.\n\nMost would get help from their family, but I don't have any left. Can you help me?", completion = "My younger brother left us when I was just comin' of age.\n\nHe sent word he would come and help but... we did not part on good terms.\n\nBut here he is. After all dis time.", objectives = "Meet Chana in the Solemn Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89585] = { id = 89585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nightfall" }
quests[89590] = { id = 89590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Time to Raid, Hope's End", description = "We require information about how multiple timerunners and their artifacts interact when faced with powerful opposition.\n\nSeek out others to help you conquer Hope's End.", progress = "Time is running short and we need that group data, {name}.", completion = "The sum strength of a group of timerunners armed with potent artifacts is greater than that of the individuals. Much greater than anticipated. Intriguing.", objectives = "Complete the Hope's End wing of Antorus, the Burning Throne on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89591] = { id = 89591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Time to Raid, Seat of the Pantheon", description = "We require information about how multiple timerunners and their artifacts interact when faced with powerful opposition.\n\nSeek out others to help you conquer Seat of the Pantheon.", completion = "The sum strength of a group of timerunners armed with potent artifacts is greater than that of the individuals. Much greater than anticipated. Intriguing.", objectives = "Complete the Seat of the Pantheon wing of Antorus, the Burning Throne on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89592] = { id = 89592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Antorus, the Burning Throne, Normal", description = "Some challenges cannot be faced alone. While numbers do matter, good teamwork is even more potent.\n\nGather your most trusted allies to help you conquer this incarnation of Antorus.", completion = "Teamwork makes the dream work, or so they say. It would appear that the rhyme carries truth to it. Hmmm.\n\n<Eternus pauses for a moment in thought.>\n\nI wonder what other rhymes carry such power. That bears some future experimentation.", objectives = "Defeat 2 bosses in Antorus, the Burning Throne on Normal difficulty or higher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
