quests[90638] = { id = 90638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bundle of Crystals", objectives = "Another task completed. The Trust thanks you for your efforts. The founder has set aside a fund to encourage such initiative.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90659] = { id = 90659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something Borrowed", description = "Now that you have your infinite bronze, we just need to select the right artifact for you, shape the bronze into a suitable simulacrum of the weapon, and then reach through a temporal knot and swap them.\n\nNo one will be the wiser.\n\nAll we have to do is remember to reclaim the simulacrum in this timeline and everything will work itself out.\n\nLet's start by selecting your specialization, that'll determine which artifact we'll be borrowing.", progress = "Every artifacts needs a mighty hero to wield it.", completion = "Intriguing. This artifact's potential has been deepened, perhaps by the fraying of this timeline. It can harness more power than any incarnation of it that I have yet encountered.\n\nLet me record that data point for Moratari.\n\nOh, important reminder--don't forget to recover the bronze simulacrum later or things might get... funky.\n\nAnd lastly, maybe don't mention to people how you got that. It could ruin the experiment.", objectives = "Select your artifact weapon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90660] = { id = 90660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Golden Circumstance", objectives = "I wish you the best of luck in all your adventures, {name}.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90661] = { id = 90661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dastardly Duos" }
quests[90663] = { id = 90663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing What is Ours", description = "Ve'nari has called in a lot of favors to get the Oasis reclamation effort off the ground. Plenty of Tazavesh merchants have donated to the cause, though some have seen fit to help themselves instead.\n\nA large shipment of stasis-sealed items was stolen from the docks by an untrustworthy importer. I could use someone of your skill to recover the shipment.", progress = "Have you recovered my missing items?", completion = "I wasn't expecting quite so much! Perhaps this is not all my imports? \n\nStill, it's good to see these items. I have a little something for your troubles.", objectives = "Speak with Xy'dax and recover the Missing Imports.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90665] = { id = 90665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carved Crests", objectives = "Another task completed. The Trust thanks you for your efforts. The founder has set aside a fund to encourage such initiative.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90666] = { id = 90666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bundle of Crystals", objectives = "Another task completed. The Trust thanks you for your efforts. The founder has set aside a fund to encourage such initiative.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90667] = { id = 90667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enchanted Runed Ethereal Crest", objectives = "Another task completed. The Trust thanks you for your efforts. The founder has set aside a fund to encourage such initiative.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90669] = { id = 90669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gold is Gold", description = "Hey! You there.\n\n<Sarvi beckons you closer and lowers her voice.>\n\nYou looking for work? A Magister gave me five gold to find an adventuring type to do some sort of job for him. He said if the person gets it done, I get five more. That'll feed me for months.\n\nYou fit the bill. If you want to try to get paid too, he has a study over by the harbor. Real fancy place--you can't miss it. The guy's name is Aradis.", completion = "Ah, so the ruffian was successful.\n\nYou do certainly look capable. Let us speak, shall we?", objectives = "Speak to Magister Aradis in his study near the Silvermoon Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90690] = { id = 90690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charge of the Vanguard", description = "Turalyon reports the Vanguard of the Light is prepared to march on Xal'atath's stronghold.\n\nWould that I could join you for the charge. I will keep my retainer of forces here to maintain the defense of the Sunwell and Silvermoon while you take the fight to our enemy. \n\nMuster in the Voidstorm, take the fight to the Voidspire, and bring an end to this great enemy. Good hunting.", sourceObjective = "Meet with Turalyon in the Voidstorm.", completion = "Good, {name}! You have made it for our charge.", sourceObjectiveStatus = "unverified-source-field" }
quests[90701] = { id = 90701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cowardly Cheery Bombs", description = "Goblins love bombs, I get that. But does EVERYTHING have to blow up?\n\nDo me a favor: In the next Dastardly Duos match you enter, find a cheery bomb inside one of the wooden tree and planter props.\n\nAfter you find the bomb, but before it  \"blows up\"... smack it for me. Don't worry, they're cowards.", progress = "Those cheery bombs are asking for it, {name}. Find one in a Dastardly Duos match and smack it!", completion = "Way to go, {name}. You have to show those bombs who's boss, you know?", objectives = "Find a Cheery Bomb, hidden inside a Dastardly prop. Smack it before it blows up.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90705] = { id = 90705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lorewalking", description = "Are you curious about your world's history? Would you like to learn more?\n\nLorewalker Cho has been traveling and gathering stories of important events and figures across Azeroth and beyond. If you pay him a visit in your capital city, he will gladly share a tale of the past with you!\n\nOr perhaps more than one tale. He does very much enjoy conversation!\n\nTell him Assistant Lali sent you.", completion = "Oh? Lali is sending vistors my way, now? \n\n<Lorewalker Cho laughs a deep, belly laugh.> \n\nOf course she is! \n\nAh, but she is correct. The only thing I love more than gathering stories is telling them! Sit down, let me share a tale with you.", objectives = "Find Lorewalker Cho in Dornogal, Stormwind, or Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90718] = { id = 90718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Request of the Arcantina", description = "Ah, {name}!\n\nI hear you have a standing invitation to Archmage Khadgar's... Arcantina?\n\nCan you go there for me and bring this missive to the Archmage? I need to source reagents for the sheer volume of telemancy spells I have been asked to conjure.\n\nMagister's Terrace has been an excellent source up until recent events but really I need the Kirin Tor to loan me some of their harder to find ingredients.", sourceObjective = "Deliver Telemancer's Request to Archmage Khadgar at the Arcantina.", progress = "Champion? Do you have something for me?", completion = "Hmm. Let's see here.\n\nWarpstalker eyes, an astral sieve-\n\nJormungar bile?! How does he plan to use that? And I am down to my last few vials. \n\nWell, it can't be helped. I will send these on to Oculeth as soon as they are gathered. In the meantime, enjoy yourself around the tavern, Champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[90719] = { id = 90719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Borrowing Corruption", description = "Adventurer, I have made an amazing discovery. \n\nAnalyzing the memories from the time I have discovered that I might be able to recreate the corruption effects that have been wielded in the past. Albeit in a much more controlled way. \n\nI will need you gather some black blood residue from defeating the bosses of the Corrupted or Lost areas of the map and a few more of the displaced corrupted mementos.", progress = "Were you successful?", completion = "Yes, by combining this residue with the displaced corrupted mementos I can... yeah just like so... and then with a bit of my bronze magic... there. Done.\n\nNow that I have a working knowledge I can also make more if you bring me additional displaced corrupted mementos. I will see if I can refine the process anymore. Check back with me later.", objectives = "Find Black Blood Residue and Displaced Corrupted Mementos from the bosses of the Corrupted and Lost areas of the Horrific Visions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90724] = { id = 90724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Broken Sky", description = "All those people. Our army. Our heroes. Our leaders.\n\nGone.\n\nWe are exposed here. Umbric's tether saved us, but we need to ensure we survive this. Report to Lor'themar and tell him what transpired in the Voidspire. I will get Umbric to safety and learn what I can here.", sourceObjective = "Report to Lor'themar in Silvermoon City.", sourceObjectiveStatus = "unverified-source-field" }
quests[90729] = { id = 90729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Win-Win Situation", description = "Not everything you recovered yesterday was mine, but let's be honest--we're going to keep it anyway!\n\nXy'daz has been ripping people off for years. It's his turn to take a loss!\n\nNow, this can work in both our favors. You sell off half of the leftover goods for me, and I'll let you keep the rest!", progress = "Did you sell the items?", completion = "You did so well! I may have to employ you more often!", objectives = "Sell 6 Shadowtrade Overstock.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90731] = { id = 90731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enhancing Corruption", description = "Welcome back adventurer. I have made a new discovery but I need to test it out. \n\nHidden in the Lost areas of the Horrific Visions I believe is a rare black blood coagulate. This might be the key to increasing the power of the corruption effects... in a safe way. \n\nIf you can go into these areas and find this item and also bring me back more displaced corrupted mementos I should be able to increase the potency of the corruption effects.", progress = "Were you successful?", completion = "Ok, this is promising... the coagulate catalyzes slower so the increased corruption is more contained... yes, this allows a higher yield of corrupted material without any negative side effects.\n\nAlas, I cannot keep it stable for long. These effects will not last. I am sorry adventurer but we should take advantage of the effects while we can. \n\nAgain, if you bring me additional displaced corrupted mementos I can make you more of these greater corruptions.", objectives = "Find Black Blood Coagulate and Displaced Corrupted Mementos from the bosses of the Lost areas of the Horrific Visions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90733] = { id = 90733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Listener", description = "Now that you've learned about our legends, you've earned the notice of one of our elders. He wants to meet you.\n\nHis name is Aksem, and he knows things that the rest of us have never learned. History that remains hidden, even in the paintings.\n\nGo and introduce yourself. He's expecting you.", completion = "Yes, I wanted to speak with you. \n\nThere are many truths that are hidden, even to the oldest living haranir. Continue to learn and they may be revealed.\n\nShow respect to our history, and I will eventually tell you more.", objectives = "Speak to Aksem in the Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90734] = { id = 90734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Name of the Goddess", description = "The high priest Aksem has asked for you again. He said you are not the only one on a quest for knowledge about the deep history of Harandar.\n\nGo to him. I believe he already has another guest who is also interested in learning this hidden history.", objectives = "Return to Aksem in the Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90735] = { id = 90735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stolen Staff", description = "This time, I do not have a story for you. \n\nInstead, Aksem has asked that you meet with him to help recover the next of the relics. Go to speak with him, and he will tell you more of what you must do.", sourceObjective = "Speak to Aksem in the Den.", sourceObjectiveStatus = "unverified-source-field" }
quests[90736] = { id = 90736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's Not Yours", description = "The rutaani in the Blossoming Terrace are crafty. They've trained their petalwings to search and grab anything shiny that rolls down from the Den.\n\nAnd, I suspect, sometimes they grab things that haven't naturally fallen.\n\nSo we want to get those things back. That's where you come in.\n\nGo into the terrace, and don't hesitate to use force to send a message. That's a language we all understand.", objectives = "Retrieve 8 Stolen Belongings from the Blossoming Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90737] = { id = 90737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nested Clues", description = "You're looking for a staff called the Root of the World. It's a powerful twist of woven roots, back from before the haranir traveled deep into the mountain.\n\nIt's irreplaceable, as Aksem knows. So if a rutaani petalwing stole it, that's embarrassing. The only way for everyone to save face is to get it back.\n\nSearch the nests of the bigger birds. They've been trained to look for more valuable items.", objectives = "Uncover clues about where the stolen rootstaff could be.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90738] = { id = 90738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Blossoming Terrace", description = "When the haranir first arrived in Harandar, they brought with them a staff formed of the roots of a great tree. That tree has since gone away, but the roots remain.\n\nIt has been our duty to protect that staff and pass it on through the generations, but now it has been stolen.\n\nYour task is to find it and return it to Zur'Ashar Kassameh.\n\nGo into the mists below the Den and seek out the Shul'ka. They will guide you on your search.", sourceObjective = "Meet Shul'ka Seila outside the Blossoming Terrace.", sourceObjectiveStatus = "unverified-source-field" }
quests[90739] = { id = 90739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Root of Things", description = "Looks like you didn't find any sign of the rootstaff among all the thiever's nests. That's a good thing, honestly.\n\nBut there's more to this test than just recovering stolen goods. Yes, it's a test. You're seeking secret knowledge. That means something here doesn't add up, and the real answer is waiting to be found.\n\nSo, come find me when you're ready to get that answer.", objectives = "Follow Shul'ka Seila and recover the missing staff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90740] = { id = 90740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Legend to Know", description = "I am entrusted with many secrets, and the benefit of that is not having to explain myself often.\n\nYou have recovered the Root of the World, as I asked. Now, take it to Zur'ashar Kassemeh, and learn more about it.\n\nThere will be more for you, later.", sourceObjective = "Return to Zur'ashar Kassameh.", sourceObjectiveStatus = "unverified-source-field" }
quests[90741] = { id = 90741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Once More Into the Rift", description = "Aksem has asked for you again. He says he's ready for you to undergo the final ritual for the knowledge he wants to teach you.\n\nI admit, I'm envious, but I do not envy the trials you'll need to undergo in order to prepare for this knowledge.\n\nGo speak to Aksem, and do as he says. Orweyna will be joining you.", sourceObjective = "Speak to Aksem, then meet Orweyna in the Rift of Aln.", completion = "<Orweyna breathes carefully and steadily, her eyes slightly unfocused. Then, she sharpens her gaze and looks at you.>\n\nI'm glad you're here. I admit, I am nervous about what we will learn. I have heard only one story of the goddess for as long as I can remember.\n\nTo know that there is more to the story, it... it fills me with curiosity and dread.\n\nBut as Aksem said, there is no going back now. And we are ready.", sourceObjectiveStatus = "unverified-source-field" }
quests[90742] = { id = 90742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shrouded by Aln'hara", description = "As you know well by now, the creatures in the rift are infused with the essence of Aln'hara. What we need is that essence mixed with water.\n\nAksem wants us to collect water here and then infuse the essence of Aln'hara into it. I can only imagine what it might be used for.", sourceObjective = "Collect water and defeat creatures in the Rift of Aln.", progress = "The voice is as strong as ever here.", completion = "It's done. But I swear... I can hear the goddess' voice mixed with pain, now. \n\nWhat are we about to learn?", sourceObjectiveStatus = "unverified-source-field" }
quests[90743] = { id = 90743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual Reinforcement", description = "You know the dangers of the Rift of Aln, but this is the best place to prepare for the kind of ritual Aksem wants to perform.\n\nGo about the rift and place offerings to prepare yourself.", sourceObjective = "Place Ritual Offerings in the Rift of Aln.", completion = "You handle the power of Aln'hara well.\n\nI'm beginning to think it was foolish to make you challenge me.", sourceObjectiveStatus = "unverified-source-field" }
quests[90744] = { id = 90744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dreamrift: Malformed Mystery", description = "We have prepared ourselves as best we can for the next stage. Now, we must venture into the deepest part of the Rift of Aln.\n\nInto the Dreamrift.\n\nIt's a place so dangerous that even the Shul'ka hesitate to go, but we must. Aksem needs us to collect the most powerful infusion of Aln there is.\n\nAre you ready?", sourceObjective = "Defeat Chimaerus in the Dreamrift.", completion = "You've survived the Rift of Aln on a number of occasions, but what walks the Dreamrift is a horror of its own category.\n\nNow you have everything you need for the ritual. I might say that the hard part is done, but that would be a lie.\n\nThe hard part is knowing the truth of the Cradle of Aln'hara.", sourceObjectiveStatus = "unverified-source-field" }
quests[90745] = { id = 90745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Empty Cradle", description = "You have ventured far, fought deep, and learned many things about our history to be here.\n\nNow it's time to know the truth. Prepare yourself.", sourceObjective = "Speak to Aksem in the Den.", completion = "Now you know.\n\nThe goddess' loss is felt most keenly here, and you understand why. It's a pain that is etched in the very land, in the water, and in the manifestations of Aln.\n\nThis is a truth that you and Orweyna will need to bear.\n\nI only hope that one day we can bring Aln'hara our comfort, to soothe her agony and her grief. This is the vow I have sworn, as have many haranir.\n\nWe will bring our goddess home.", sourceObjectiveStatus = "unverified-source-field" }
quests[90746] = { id = 90746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Elves Assemble", description = "The time for preparations have passed. Xal'atath's forces are upon us.\n\nJoin us, champion, as we must rebuff this assault and then press our attack on the Darkwell.", sourceObjective = "Speak to Arator at the war table.", sourceObjectiveStatus = "unverified-source-field" }
quests[90747] = { id = 90747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wrong Bluecephalus", description = "We may have gotten off on the wrong foot, but there's something you should know.\n\nThat old slateback you used to haul all those imports? I thought it was just another worn-out nag, but it turns out it was the real treasure all along.\n\nA rare bluecephalus, worth a fortune!\n\nYou might want to figure out where it went, and why Ba'eth isn't exactly rushing to share the profits!", progress = "Are you ready to help?", completion = "Good. This will be a profitable venture... for me.", objectives = "Speak with Ba'eth and others.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90748] = { id = 90748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quel'Danas", description = "Champion, the time has come to see an end to the Darkwell.\n\nI do not know what awaits us beyond the gates of Quel'Danas, but we cannot tarry any longer. The Void continues to pour into the Darkwell, transforming it. \n\nArator is at the head of our combined armies. He has asked you and your strongest allies join him at his side. \n\nIt is time to end this and take back our well.", sourceObjective = "Meet with Arator before the gates of Quel'Danas.", completion = "Here we stand. Here we fight.", sourceObjectiveStatus = "unverified-source-field" }
quests[90749] = { id = 90749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Mutual Enemy", description = "<Liadrin lowers her voice, speaking only to you.>\n\nWe have two choices. We can either continue to talk to the Amani or fight our way inside.\n\nI would still prefer to negotiate passage with Zul'jarra, but if our diplomacy goes awry, be ready.\n\nFor now, follow my lead.", completion = "I must say I am... surprised that Zul'jarra allowed us passage. It has been many years since I or anyone from Eversong has stepped foot on this side of the border.\n\nStay sharp. This is a volatile situation. We may have to do more to engender their trust.\n\nBut don't turn your back on the Amani.", objectives = "Follow Lady Liadrin into Zul'Aman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90751] = { id = 90751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lumber Processing" }
quests[90754] = { id = 90754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skyriding", description = "This land is more vast than I remember. However, a good scholar is always prepared.\n\nTo cover more ground, you will need a winged mount and the skill to ride it swiftly.\n\nI recall Lord Andestrasz helping us with this in the past, near the Timeless Isle in Pandaria. Let's send you back to that moment in time, so you can learn from him.\n\nDon't wander too far in distant lands, you're still needed back here. Return via the portal when you have finished your instructions.", progress = "All things come with practice.", completion = "Let us get started. We will focus on the basics.\n\nDo not worry, the fancy maneuvers will come later.", objectives = "Take Moratari's portal to Lord Andestrasz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90755] = { id = 90755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time Flies", description = "That should suffice for now. Remember the basics and you will improve in time.\n\nSpeaking of time, you had best be on your way. The portal there will take you back to Moratari.", completion = "Excellent. This should expedite our research.", objectives = "Return to Moratari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90759] = { id = 90759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cult Within", completion = "Thank you for coming, {name}. The Twilight's Blade cannot be allowed to roam our cities.", objectives = "Meet Magister Umbric in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90760] = { id = 90760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avoiding Blame", description = "Apocalyptic threats have taken many forms in Azeroth's history, but today we face Xal'atath and her Twilight's Blade.\n\nI fear that people are falling into hopelessness as the Radiant Song cries a warning. The Twilight's Blade could use that despair to draw them into their ranks.\n\nMy mages have identified this district as housing a peculiar amount of void energy. Investigate and stop any cultists you may find.", progress = "I understand the comfort the void can provide. But surrendering to it completely is not the peace many are led to believe.", completion = "There are Twilight's Blade in the city. If they are here, they are certainly recruiting elsewhere.\n\nWe have more work to do.", objectives = "Disperse 6 Suspicious Citizens in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90761] = { id = 90761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avoiding Blame", description = "The cult of twilight has long been dedicated to ending Azeroth. That they ally with Xal'atath is no surprise.\n\nIf the Twilight's Blade are indoctrinating citizens, we must stop them. We cannot permit the weak to fall to the Void's dark designs.\n\nThe Cleft of Shadow is home to many practitioners of unsavory magic. Identify and end any cultists you may find there.", progress = "<Rommath sneers at you.>\n\nThe calm and comfort the Void offers is a lie. You would do well to abandon it.", completion = "The Radiant Song casts a long, dark shadow on Azeroth. The Twilight's Blade are taking advantage of it.\n\nWe have work to do.", objectives = "Disperse 6 Suspicious Citizens in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90762] = { id = 90762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Highlands", description = "I've spoken with Grand Magister Rommath. Despite our differences, it seems we are aligned in purpose.\n\nWe have both found evidence that Twilight's Blade cultists are convening in the Twilight Highlands. It's a place long scarred by the cult's misdeeds. And it's a suitable staging ground for an attack.\n\nMeet us there so we may continue our investigation.", completion = "Well. It seems we are to be working together to investigate the Twilight's Blade.\n\nI do hope you're prepared.", objectives = "Meet Grand Magister Rommath in the Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90763] = { id = 90763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Highlands", description = "I've received word from Magister Umbric. He has found similar evidence that the Twilight's Blade are recruiting in Stormwind.\n\nThe Void poses an existential threat to all of Azeroth. We must stop the cult at its source.\n\nWe've agreed to meet in the cult's homeland, the Twilight Highlands. Find me there so we may continue our investigation.", completion = "Good, you've arrived. \n\nKeep an eye on our allies. We may be working with them to stop the Twilight's Blade, but the Void is insidious. \n\nThey cannot be fully trusted.", objectives = "Meet Grand Magister Rommath in the Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90764] = { id = 90764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cult Within", completion = "Good, you're here. We cannot let the Twilight's Blade gain ground in the city.", objectives = "Meet Grand Magister Rommath in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90765] = { id = 90765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight Dress", description = "Cult activity in the area has risen significantly. While we are gathering troops, you secure a cultist disguise and infiltrate their nearby training grounds.\n\nFind out anything you can about the Twilight's Blade and their goals. I will keep this area secure.", progress = "You look lost, fledgling. Isn't there somewhere you should be?", completion = "You hardly seem prepared to serve Xal'atath. We shall fix that.", objectives = "Find a Twilight's Blade disguise and infiltrate the Twilight's Blade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90766] = { id = 90766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xal'atath's Proven Faithful", description = "It takes more than blistering desperation for the apocalypse to be part of the Cult of Twilight.\n\nWe are Xal'atath's Twilight's Blade. Our purpose is greater than it has ever been before. And thus, we must become her strongest allies.\n\nGo and train with my associates in the field. Educate yourself on our rituals and rhetoric. Only then will I allow you to go through the initiation ceremony.", completion = "Excellent. You have the bearing of a true acolyte of the Twilight's Blade.", objectives = "Train to become a Twilight's Blade cultist.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90767] = { id = 90767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Doom", description = "Having completed your training, you have earned full membership with the Twilight's Blade.\n\n<Harrowtongue pauses a moment, appearing self-satisfied.>\n\nAs a member of the cult, you will now join your fellow acolytes in an initiation ceremony. They are in the basement of this building receiving instructions from our great leader, Mor'duun.\n\nAllow his words to fill you with zeal for the cause. The end is near!", progress = "Have you discovered more about the cult's plans?", completion = "I suppose aligning with yet another being hellbent on ending the world is only fitting for the Cult of Twilight.", objectives = "Sabotage the ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90768] = { id = 90768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cult It Out", description = "Mor'duun and his Twilight's Blade cultists are directly supporting the Harbinger's dark designs for our world.\n\nAnd that is all we need to know. Kill as many as you can, then meet us back at our base of operations.\n\nThe cult and its leaders must be eliminated.", completion = "Their nefarious alliance with Xal'atath is clear. Good work. Now we take them down.", objectives = "Kill Gehl Harrowtongue and 12 Twilight's Blade cultists.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90769] = { id = 90769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blue for You", completion = "May the spirits protect you mon, and your new blue friend!", objectives = "Receive your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90770] = { id = 90770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grift", description = "Dey say you want the blue beast. Was a great bargain I stumbled upon. Da bazaar full of opportunities. \n\nMany more bargains to find in spots where treasures lie waiting. \n\nYou know where to look?\n\nGo to dis special place and find treasures, I give the blue beast to you.", progress = "Did you find da treasures?", completion = "Good work, mon. Griftah be smiling today.", objectives = "Enter Untethered Space and recover the items Griftah requires.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90772] = { id = 90772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Flames Rise Higher", description = "De coal... it's white-hot now. And I feel like there is somethin' inside it?\n\nBrek said dis was de last trial. But Jan'alai is not here.\n\nWhat do we do now?\n\n<Zul'jarra looks at Brek and scowls.>\n\nTalk to Brek and see if he's got anything to say we can understand.", progress = "If I cannot commune with Jan'alai, de path of de hash'ey stops at dis temple.", completion = "We did it, hash'ura.\n\nJan'alai is reborn! And we have her blessin'.\n\n<Zul'jarra closes her eyes and briefly enjoys the feeling of the flame against her face.>", objectives = "Complete the ritual of Jan'alai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90773] = { id = 90773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meat My Business", description = "Since I am helping you, I'm sure you won't mind returning the favor.\n\nI have a constant need for fresh, untainted meat, which is quite hard to come by. The Oasis is off limits, but the wildlife roaming these sands?\n\nI've got a list of what I need. Bring me those items, and I'll tell you what you need to know.", progress = "You've collect all the meat?", completion = "Now as I promised.\n\nI sold the blue slateback to an outsider like yourself. Not some great hero, but more of an awkward sort.\n\nCome back tomorrow. He usually stops by here for a meal. And he doesn't merely smell it, he eats!", objectives = "Collect 12 Dustback Flank, 5 Siltwing Tail, and 5 Swoopwing Eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90776] = { id = 90776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Curiosity: Combat", description = "<You hold the curio and discover a shimmering glow emanating from it. This looks important. The Explorers' League would be interested in this.>", objectives = "Use and equip a Combat Curio to Brann Bronzebeard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90777] = { id = 90777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeding the Flame", description = "Champion, the Sunwell holds for now, but the Vanguard has begun to deploy the bulk of its forces to Voidstorm.\n\nLady Liadrin has requested your assistance at the Sunwell.", sourceObjective = "Speak to Liadrin at the Sunwell.", progress = "It's heartening to see our commanders so eager to bring the fight to the enemy.", completion = "We persevere for now, {name}. The quicker we face Xal'atath at the Voidspire, the quicker this can all be behind us.", sourceObjectiveStatus = "unverified-source-field" }
quests[90778] = { id = 90778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Curiosity: Utility", description = "<You hold the curio and discover a shimmering glow emanating from it. This looks important. The Explorers' League would be interested in this.>", objectives = "Use and equip a Utility Curio to Brann Bronzebeard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90779] = { id = 90779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cracked Keystone", description = "Fragmentary images of heroic deeds flash though your mind as you touch the stone, but they fade as fast as they arrive.\n\nPerhaps performing a suitably impressive task will stabilize the stone's magic once more?", objectives = "Complete any dungeon on Mythic 2 or higher difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90781] = { id = 90781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparks of War: K'aresh", description = "There's rumors about conflict rising in K'aresh - go off and find out more!", progress = "Go off and finish what you started.", completion = "I'm astounded at your quick return, well done.", objectives = "Collect 100 Sparks of War in K'aresh, while in War Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90782] = { id = 90782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nethersent", description = "<The draenei first tries to speak to you in his native tongue, adapting after you fail to respond.>\n\nMen of Void take us to here. Come from sky. Fighting, killing. Want to go back. Help brothers and sisters.\n\nShow you.", completion = "<The woman seems wary of you, but nonetheless bows at your approach.>\n\nFriend? Hope of us.", objectives = "Free the draenei and meet with him at the base of Masters' Perch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90818] = { id = 90818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murder Row: Loose Lips", description = "It is not unexpected to sense some fel magic here. There are still warlocks in the city and old fel siphoning chambers. But the evidence I've found so far is more than could be explained by just that. It feels... different. Chaotic.\n\nThis practice has to be widespread, which means someone must be talking about it.\n\nI've been rooting around too long to go unnoticed, but perhaps you could covertly listen in on some idle banter around the city. If you learn anything useful, report back to me.", progress = "People let many things slip when they assume they're unheard.\n\nNever assume you're unheard.", completion = "<Belath's expression sours more than usual.>\n\nFear drives people to desperate measures, but fel magic isn't a weapon to be wielded lightly.\n\nThe power comes at a cost they do not understand--nor are they trained to withstand those dangers.", objectives = "Listen in on 3 conversations near the Royal Exchange.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90819] = { id = 90819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murder Row: Acting the Part", description = "Based on what we discovered, I believe the fel is coming from Murder Row. Someone there is breaking down Legion relics and infusing the magic into mana wyrms for covert siphoning--and people are buying it up in droves.\n\nWe need to figure out who that someone is.\n\nTake this wyrm core with you into the Row and look for more of them. The promise of coin should get you in front of the right person.", progress = "The denizens of Murder Row are tight-lipped, but any information we manage to uncover will be invaluable.", completion = "They mentioned someone named Zaen?\n\nHe's a well-known thug in the Row. Smuggling fel through the Silvermoon Harbor sounds exactly like his style. He doesn't want anyone watching him.\n\nGood work pocketing that shipping manifest.", objectives = "Take the Cracked Wyrm Core, then investigate Murder Row to discover the source of the smuggled fel wyrms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90821] = { id = 90821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murder Row: Harbored Secrets", description = "That manifest is stamped by the Silvermoon Harbor. It looks like Zaen has his smugglers working there to push his fel relic shipments through inspections.\n\nIf we cut off their supply line at the harbor, we can halt the fel operation until we track down Zaen and end it for good. No sense going after the middlemen until then.\n\nSubterfuge got us this far, so let's keep at it. Head to the harbor and tell them you're picking up Zaen's shipment. We'll work from there.", progress = "Zaen is the mastermind here, or at least he seems to be. We'll need to deal with him to truly end this scheme.\n\nTaking out their fel supply line at the harbor will stop the situation from getting any worse while we find him.", completion = "The \"Illicit Rain?\" Zaen's base of operations, perhaps.\n\nThat receipt mentions Suramar. The fel relics must be getting pilfered from the Broken Isles, then routed into Silvermoon through a trade line no one would suspect.\n\nClever.", objectives = "Talk to the dockmaster at the Silvermoon Harbor to collect Zaen's fel relic shipment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90822] = { id = 90822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murder Row: One Fel Swoop", description = "We have all the puzzle pieces. Zaen smuggles fel relics from the Broken Isles by stacking the Silvermoon Harbor with his own smugglers. The relics are processed in Murder Row, then fel magic is infused into mana wyrms for sale and siphoning.\n\nSuch a convoluted operation might be impressive, if the goals weren't so reckless. Zaen is preying on people's fear. He doesn't care who he helps or hurts as long as he rakes in the gold.\n\nLet us end it. We'll find the Illicit Rain in Murder Row and clear it out.", progress = "Something seems to have happened in Murder Row since we left. A crowd is forming.\n\nProceed with caution. I'm with you.", completion = "With no one left to run it, this fel operation should be done with... for now, at least.\n\nIt was a pleasure working with you, {name}.", objectives = "Dismantle the fel smuggling operation inside Murder Row.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90824] = { id = 90824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Brother's Alive!", description = "En'liahn saved me from the Rift of Aln. He's my older brother. I know it was stupid to go there, but it wasn't my fault!\n\nWe all thought En'liahn was dead, but I saw him earlier at the wetland. When he saw me, he ran away.\n\n<Chua looks sad.>\n\nNo one here believes me and now I can't go. Will you help me find him again?", completion = "Chua sent you? He's not out here again is he?\n\nMind lending me a hand?", objectives = "Find En'liahn at the Ahl'ua Wetland.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90826] = { id = 90826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Healing Waters of Ahl'ua", description = "I'd hoped Chua hadn't seen me. Better he thinks I died. Instead, I'm self-exiling.\n\nI was trapped in the Rift of Aln while saving him. Being in there for so long corrupted my connection to the goddess--if I don't sever it soon, it'll drive me mad, or worse.\n\nThe Shul'ka who saved me has agreed to mentor me through the process. He told me to come here and gather some things for a ritual to sever the connection.\n\nI must collect the nearby healing waters. Will you help me fill this jug?", progress = "I appreciate your help, {name}.", completion = "Thank you, {name}.\n\n\n\nI hope the water is as powerful as my mentor says it is. The strong poison of these creatures suggests I'm going to need it to survive the ritual.", objectives = "Collect 6 Healing Waters of Ahl'ua.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90827] = { id = 90827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Only the Poisonous Parts", description = "My Shul'ka mentor instructed me to collect the toxic glands from the creatures here. He said they were crucial to the Ritual of Severing in order to break my connection with the goddess.\n\n<En'liahn shakes his head in pain.>\n\nI'm not looking forward to whatever this ritual is, but her disjointed song in my head is getting stronger and making it hard to focus.", progress = "Be careful handling that poison. These creatures are some of the deadliest in all of Harandar.", completion = "This should be more than enough.\n\nI'll be careful with them. I wouldn't want to poison myself prematurely.", objectives = "Collect 8 Phytogenic Poison Parts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90829] = { id = 90829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meeting My Mentor", description = "I'm in your debt, {name}. I didn't think I'd get any help. My mentor only provides guidance. He says that is the way of the Shul'ka.\n\nThanks to you, I have everything I need for the ritual. Will you continue on with me? I'm heading for the cliffside overlooking the Rift of Aln to the northeast.", completion = "I'm glad you came. Amarakk is my Shul'ka mentor. He says your help is not strictly forbidden.\n\nI can use all I can get.", objectives = "Rejoin En'liahn on the cliffside above the Rift of Aln.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90830] = { id = 90830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path Will Reveal Itself", description = "The next step is to locate the ritual site. It's different for each potential Shul'ka.\n\nAmarakk says that I must open myself to the power of the rift--that some part of myself tied to this place will guide the way.\n\nAll I can tell you is it hurts.\n\nAre you still with me?", progress = "I see you made it.", completion = "Now it is time to see if young En'liahn will survive the ritual or be consumed by the rift.", objectives = "Travel with En'liahn to discover the ritual site within the Rift of Aln.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90831] = { id = 90831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doing Is Becoming", description = "If En'liahn is to succeed as a Shul'ka, he must learn to disrupt the manifestations in the rift. Sometimes that means closing small tears as they open. Most of the time, we simply slay the manifestations where we find them so they do not become so numerous as to threaten the rest of Harandar.\n\nIt is a never-ending responsibility each of us bears. It is why we are Shul'ka.\n\nThis, of course, assumes that he survives the ritual, or even survives to find the ritual site.", progress = "I see you, {name}.", completion = "You have done well for one who is not Shul'ka.\n\nUnfortunately, the Rift of Aln never rests. I think you'll be back.", objectives = "Disrupt the manifestations within the Rift of Aln.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90832] = { id = 90832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "As Her Voice Goes Silent", description = "En'liahn is about to drink the mixture of the poison and healing waters to begin the ritual. He will be unconscious and fighting for his life.\n\nThe manifestations of the rift can sense this, and they are gathering.\n\n{name}, you must place the wards and use their power to defend him while he severs his final connection to the goddess before her song drives him to madness.", progress = "Whatever happens next, you've proven you can be trusted.", completion = "It is done. There is but one thing left to do once En'liahn has recovered.\n\nBut first, we should leave the rift immediately. This is no place to linger.", objectives = "Protect En'liahn while he endures the Ritual of Severing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90833] = { id = 90833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Rite", description = "Foolish. En'liahn is still weak from the ritual and not prepared.\n\nHe has run off to confront Morta'ka the Sundered Echo. This is the final rite of all who would become Shul'ka, but it is usually only attempted after years of preparation.\n\nEn'liahn will not survive, and in dying will only make Morta'ka more powerful. Will you save him, {name}?", completion = "I know it was stupid and I should be dead. I feel confused about surviving the ritual but no longer being able to hear the goddess. I'm sorry, {name}. I shouldn't have done that.\n\nAt least it's over. Now to apologize to Amarakk. He's probably done with me.", objectives = "Help En'liahn to slay the manifestation known as Morta'ka the Sundered Echo inside the Shadow Cleft.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90834] = { id = 90834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From This Point Forward", description = "I don't know how to feel about losing my connection with Aln'hara. There's no more pain... I'm not going mad, but there's a hole inside. Does that make sense?\n\nWill you rejoin us back up on the cliff?", completion = "I owe you a great debt, {name}. At least now I can protect my people as I learn the ways of the Shul'ka.\n\nMy only regret is being separated from Chua.", objectives = "Return to En'liahn and Amarakk on the cliff overlooking the Rift of Aln.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90835] = { id = 90835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murder Row: Rumors Abound", description = "I would advise exploring the city with caution. Not all is what it seems in Silvermoon.\n\nThe Illidari are performing an investigation which need not be spoken of openly. But you appear formidable... Perhaps you can aid us.\n\nMy commander, Belath Dawnblade, is heading the investigation. The last I heard, he was surveying the upper terraces of the Bazaar.\n\nSeek him out, if you would make use of yourself.", completion = "Your arrival is timely.\n\nI will be brief: I believe there is a widespread resurgence of fel magic use happening in Silvermoon, and it must be stopped.", objectives = "Find Belath Dawnblade in the terraces above the Bazaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90837] = { id = 90837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murder Row: Traces of Fel", description = "I have been sensing powerful fel magic throughout Silvermoon, but this is the first origin point I could locate. The rest were too faint, or perhaps deliberately hidden. Fortunately, this means we now have a specific area to comb through more closely.\n\nWe need to gather more evidence. Go around this area and see if you can find more hidden sources of fel. I will grant you a temporary portion of my sight so that even the slightest hint of fel magic will be obvious to you.", progress = "Were you able to locate anything?", completion = "Hm... Legion scraps, fel dust, and evidence that both might be getting moved around the city covertly. A sanctioned fel trade would not be resorting to such measures.\n\nThen there are the mana wyrm cores we both found. Siphoned dry, but fel still clings to them.", objectives = "Discover 5 sources of fel magic near the Royal Exchange.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90838] = { id = 90838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oaths and Heirlooms", description = "You, stranger... do you know of the Shadowguard that left K'aresh in ruins?\n\nMy sister was lost in the conflict, her heart forcibly turned to the Void, but I swore oaths to my family... to cherish them no matter their transgressions.\n\nMy sister, Veraan, is surely lost, but if I were to recover her necklace, at least then my oaths would be upheld in spirit.\n\nI am a simple tinkerer. I've tuned this device to track the Shadowguard, but I cannot face them alone.\n\nWould you help me?", completion = "Keep yourself out of sight. I would rather not risk a bleak fate.", objectives = "Meet Kifaan outside of the Ethereum Overcroft.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90840] = { id = 90840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Your Specialty?", description = "The Dragon Isles is a dangerous and uncharted place. We'll need to get you prepared.\n\nYou're strong enough now that you should choose a combat specialization.\n\nThis will unlock a new array of abilities for you to face the dangers within the Dragon Isles.\n\nGo ahead and choose your combat specialization.", progress = "Having trouble? You can find your combat specialization beside your spellbook.", completion = "Excellent choice! I'm looking forward to what you do next.\n\nTake this riding mount. It'll help you get around here faster.", objectives = "Choose your combat specialization.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90842] = { id = 90842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home Is Where the Hearth Is", description = "Before you head off, you'll want to get yourself a Hearthstone. \n\nThis little stone will return you to the inn where you last bound it to.\n\nIt's not much of an \"inn\", but the explorers have a tent set up. \n\nTest out that new mount of yours and ride over to Sil'nori Crestshade. He'll get you sorted out with a Hearthstone.", progress = "Sil'nori Crestshade nearby can get you set up with a Hearthstone.", completion = "If you ever find yourself lost, use your Hearthstone to get yourself back to where you should be.", objectives = "Ride your mount, then speak with Sil'nori Crestshade to get a Hearthstone bound to the Wild Coast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90843] = { id = 90843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding the Dragon Isles", description = "It's time for us to part ways. I have pressing business further within the Dragon Isles in a place called the Azure Span.\n\nNaleidea Rivergleam of the Dragonscale Expedition could use your help.\n\nSafe travels, {name}. I look forward to our next meeting!", completion = "How are you? We could use more hands to help us explore the Dragon Isles!", objectives = "Meet  Naleidea Rivergleam to begin your adventure in the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90844] = { id = 90844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fits of Lucidity", description = "While I've been lurking, I've been listening.\n\nThese Shadowguard appear to have a minor rebellion on their hands. Some of the ethereals are acting erratically. They're being rounded up and questioned.\n\nWhat's going on here?\n\nDispatch some of these Shadowguard and intercept their intel. I'll decode anything you bring back to me.", progress = "I thought the Void coursing through these ethereals was all-consuming.\n\nAnd yet, there seem to be some able to resist its infinite darkness.", completion = "Something has sparked a rebellious fire in some of the Shadowguard.\n\nLet us see what more we can find.", objectives = "Slay ethereals in the Ethereum Overcroft and collect 8 Interrogated Data.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90845] = { id = 90845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distant Memories", description = "I swore an oath to honor my family... difficult when my sister was converted to the Shadowguard. She may not be here, but tracking the Shadowguard has led me to this place. \n\nI'm looking for a necklace that belonged to my sister Veraan. It's odd... I've noticed many K'areshi heirlooms discarded around here. It seems the Shadowguard wish to destroy any reminders of our home world.\n\nIf you bring some of these trinkets and baubles to me, we can see if there are any I recognize.", progress = "These keepsakes are some of the last remnants of our home world.\n\nThe memories they contain are powerful. The Shadowguard is right to fear them.", completion = "I do recognize some of these items! They belonged to close friends and family.\n\nIf my sister's necklace is to be found, it will be here.", objectives = "Collect 8 K'areshi Keepsakes found at the Ethereum Overcroft.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90847] = { id = 90847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truth From Power", description = "Thanks to your intel, we have learned that the rebels are being interrogated by Questioner Xen'daan.\n\nIt is said that after being questioned, the rebel ethereals are being taken somewhere to be \"dealt with.\"\n\nThe head questioner is sure to know more. If we can find where they've taken the rebels, there may still be hope for them.", progress = "At the risk of getting my hopes up... do you think Veraan could be among them?\n\nCould I face her now? After the atrocities she's committed in the name of the Void?", completion = "{name}! This necklace belongs to Veraan! Veraan IS Sombersong!", objectives = "Slay Questioner Xen'daan at the Ethereum Overcroft to discover the rebels' whereabouts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90848] = { id = 90848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "She Started the Fire", description = "Veraan is sure to be amongst the rebels taken to Shadowguard Point.\n\nHer fiery spirit fills me with great pride!\n\nI came here expecting to say a farewell of sorts. I did not come here expecting to find my sister.\n\nPerhaps it's not too late, {name}!", completion = "Veraan's essence may have been twisted by the Shadowguard, but the rebellion gives me hope.\n\nCan the dissidents be snatched from the Void's grip entirely?", objectives = "Meet Kifaan at Shadowguard Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90849] = { id = 90849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light Show" }
quests[90851] = { id = 90851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eating Their Own", description = "The Shadowguard seem to have no qualms caging and torturing their own kind.\n\nThe last thing I want is more violence amongst the people of K'aresh, but better them than us.\n\nDisrupt their operation by subduing some of the Shadowguard.", completion = "Violence is rarely an occasion for celebration, but I am glad we have at least slowed the deeds occurring here.", objectives = "Slay 12 Shadowguard Engineers and Infusers at Shadowguard Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90852] = { id = 90852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Techno-Magnetic Pulse", description = "The betrayers are being held in stasis chambers.\n\nI've seen these cages before. Their design is efficient but fragile. They will fail with the slightest energy variation.\n\nFind crackling energy vessels strewn about and heave them at the stasis chambers. With true aim, you will disable them and free the betrayers.", completion = "Thank you, {name}. You helped me see my sister again. For that, I can never repay you.\n\nVeraan is changed. Angry. Tormented by despair. Let us tread delicately.", objectives = "Throw Crackling Energy Vessels at arcane prisons to free the Caged Betrayers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90858] = { id = 90858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repress the Oppressors", description = "We were brought here to face the wrath of Soulbinder D'zaar. She commands the Shadowguard here. She leverages the power of the Voidstorm to convert souls to energy that she consumes.\n\nShe and her loyalists are traitors to our kind!\n\n<Veraan grimaces in pain as the Void courses through her.>\n\nThey must be stopped... their devices dismantled... their will ended...\n\n{name}... destroy them all!", progress = "<Veraan trembles with rage.>\n\nThese kinslayers were willing to sacrifice their own. And in service of what? Xal'atath's will?", completion = "I can feel Kifaan's hesitation every time our gaze meets. He is afraid of me...", objectives = "Disrupt the operation by slaying ethereals, destroying Fragile Energy Piping, and detonating Volatile Energy Reservoirs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90860] = { id = 90860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shedding the Yoke", description = "Rebels like us are brought to Soulbinder D'zaar. She suffers no betrayers.\n\nOur fate was to be sacrificed--our souls converted to energy. D'zaar works the conduit with arcane mastery to absorb these souls!\n\nWe don't have much time. I can feel the Void pressing from within. If we are to leave this life violently, D'zaar and her conduit are coming with us!", progress = "The pressure is building... it's almost time...\n\nAnd besides, do I even deserve to live? What will they say of me, a member of the Shadowguard, when all is said and done?\n\nDo you think Kifaan could ever forgive me?", completion = "The Shadowguard got what they deserved.\n\nBut I am not blameless, {name}. Even now, shadows linger inside me.\n\nFor the safety of everyone, I should go.", objectives = "Slay Soulbinder D'zaar at Shadowguard Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90861] = { id = 90861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Those Left Behind", description = "In the wake of Xal'atath's destruction, what remains of our forces are gathering at the Darkwell to determine what we can do about the remnants of the Void.\n\nWe cannot abide the presence of so much dark energy. Some of our greatest casters and most knowledgeable scholars believe they might have a solution, but we could use your aid.\n\nPlease, join Arator at the Darkwell at your earliest convenience.", sourceObjective = "Seek out Arator at the Darkwell.", completion = "Thank you for coming. It is fitting we have you here for this day.", sourceObjectiveStatus = "unverified-source-field" }
quests[90862] = { id = 90862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Times of Need", description = "The last of the other elven leaders have returned with powers from their homeland that will help us in cleansing the Darkwell. \n\nWhile the Voidstorm no longer barrages the Darkwell, it still needs healing. \n\nPlease meet with the other leaders and let them know we are ready for them.", sourceObjective = "Speak with each of the elven leaders.", completion = "Elves of all nations have spent ages upon ages drawing upon wells for magic, for life, and for identity. Not even the dragon aspects could surpass our knowledge in this hour.", sourceObjectiveStatus = "unverified-source-field" }
